import type { ImageSourcePropType } from 'react-native';

/**
 * Card art registry. GENERATED by scripts/bundle-cards.mjs — edit that, not this.
 *
 * Every card is BUNDLED at 480x643, as JPEG.
 *
 * THE EXTENSION MUST DESCRIBE THE BYTES. Supabase's object keys are named
 * `.webp` but its transform endpoint returns JPEG, and the first version of
 * this file saved the downloads under the source key's extension without
 * looking at them. Android rendered them anyway (Fresco sniffs content); iOS
 * resolves a bundled resource by its declared type, failed to decode, and
 * every card on the board fell back to CardTile's glyph placeholder. The local
 * files are `.jpg` because they ARE JPEG. The remote URLs below stay `.webp`
 * because that is the real key on the server, whatever the bytes are. A board tile draws about 240
 * physical px on a 3x phone (the board is capped to a 480pt column in
 * app/_layout.tsx), so 480px is roughly 2x oversampled and stays crisp on
 * iPad without shipping pixels nothing ever renders.
 *
 * The full-resolution 1792x2400 originals remain on Supabase and are used as a
 * fallback for any id missing from the bundle, so a partial bundle degrades to
 * streaming rather than to a blank card.
 *
 * The Spanish name is painted INTO the art, which is why CardTile suppresses
 * its own name plate (see `isBakedCard`) — and why the bundled width is chosen
 * for legibility of that banner rather than for the tile size alone.
 *
 * NOTE: video is deliberately NOT bundled. The clip set is 1,258 MB and fits
 * under no store limit; it stays streamed and capped per round.
 */

